<template>
  <AppFrame>
    <section class="heading mb-6"><div><p class="eyebrow mb-2">TRAZABILIDAD</p><h1 class="text-h4 font-weight-bold">Mantenimientos</h1><p class="text-medium-emphasis">Encuentra reportes y evidencias en segundos.</p></div><v-btn prepend-icon="mdi-refresh" variant="tonal" :loading="loading" @click="load">Actualizar</v-btn></section>
    <v-card class="filter-card mb-5" elevation="0" rounded="xl"><v-card-text class="pa-5"><v-row align="center"><v-col cols="12" sm="6" md="3"><v-text-field v-model="filters.fecha" type="date" label="Fecha" prepend-inner-icon="mdi-calendar" clearable hide-details variant="outlined"/></v-col><v-col cols="12" sm="6" md="3"><v-select v-model="filters.maquina" :items="machines" item-title="nombre" item-value="id" label="Máquina" prepend-inner-icon="mdi-cog-outline" clearable hide-details variant="outlined"/></v-col><v-col cols="12" sm="6" md="3"><v-select v-model="filters.tecnico" :items="technicians" item-title="nombre" item-value="id" label="Técnico" prepend-inner-icon="mdi-account-hard-hat-outline" clearable hide-details variant="outlined"/></v-col><v-col cols="12" sm="6" md="3" class="d-flex ga-2"><v-btn color="primary" class="flex-grow-1" :loading="loading" @click="load">Buscar</v-btn><v-btn icon="mdi-filter-off-outline" variant="tonal" @click="clearFilters"/></v-col></v-row><div class="d-flex align-center mt-4"><span class="text-caption text-medium-emphasis">{{records.length}} mantenimiento(s) encontrados</span><v-spacer/><v-chip color="success" size="small" variant="tonal" prepend-icon="mdi-image">Evidencias disponibles</v-chip></div></v-card-text></v-card>
    <v-card class="panel" elevation="0" rounded="xl"><v-data-table :headers="headers" :items="records" :loading="loading" hover><template #item.fecha_hora="{item}"><div class="font-weight-medium">{{dateOnly(item.fecha_hora)}}</div><div class="text-caption text-medium-emphasis">{{timeOnly(item.fecha_hora)}}</div></template><template #item.maquina.nombre="{item}"><div class="font-weight-medium">{{item.maquina?.nombre}}</div><div class="text-caption text-medium-emphasis">{{item.maquina?.codigo}}</div></template><template #item.tecnico.nombre="{item}"><div class="d-flex align-center ga-2"><v-avatar color="primary" size="30" variant="tonal">{{initials(item.tecnico?.nombre)}}</v-avatar>{{item.tecnico?.nombre}}</div></template><template #item.evidencia="{item}"><div class="d-flex ga-1"><v-avatar v-if="item.foto_url" rounded="lg" size="38"><v-img :src="item.foto_url" cover/></v-avatar><v-icon v-if="item.audio_url" color="primary" icon="mdi-microphone"/><span v-if="!item.foto_url&&!item.audio_url" class="text-caption text-medium-emphasis">Sin evidencia</span></div></template><template #item.estado="{item}"><v-chip color="success" size="small" variant="tonal">{{item.estado}}</v-chip></template><template #item.actions="{item}"><v-btn color="primary" variant="text" @click="openDetail(item.id)">Ver detalle</v-btn></template><template #no-data><div class="pa-10 text-center text-medium-emphasis"><v-icon icon="mdi-clipboard-text-search-outline" size="42"/><p class="mt-3">No hay mantenimientos con estos filtros.</p></div></template></v-data-table></v-card>
    <v-dialog v-model="dialog" max-width="900"><v-card v-if="detail" rounded="xl"><v-card-item :title="detail.maquina?.nombre" :subtitle="`${detail.tecnico?.nombre} · ${new Date(detail.fecha_hora).toLocaleString()}`"><template #append><v-chip color="success">{{detail.estado}}</v-chip></template></v-card-item><v-divider/><v-card-text class="pa-6"><v-row><v-col cols="12" md="7"><h3 class="text-subtitle-1 mb-3">Evidencia fotográfica</h3><v-img v-if="detail.foto_url" :src="detail.foto_url" height="330" cover rounded="lg"/><v-sheet v-else class="empty-evidence" rounded="lg"><v-icon icon="mdi-image-off-outline" size="44"/><span>Sin fotografía registrada</span></v-sheet></v-col><v-col cols="12" md="5"><h3 class="text-subtitle-1 mb-3">Observaciones</h3><p class="text-body-2">{{detail.observaciones||'Sin observaciones generales.'}}</p><h3 class="text-subtitle-1 mt-7 mb-3">Nota de voz</h3><audio v-if="detail.audio_url" :src="detail.audio_url" controls class="audio"/><v-sheet v-else class="pa-4 text-caption text-medium-emphasis" border rounded="lg">No se adjuntó audio.</v-sheet></v-col></v-row><v-divider class="my-6"/><h3 class="text-subtitle-1 mb-2">Cumplimiento del checklist</h3><v-list density="compact"><v-list-item v-for="item in detail.detalles" :key="item.id" :title="item.cumple?'Punto verificado':'Punto no verificado'" :subtitle="item.observacion_item"><template #prepend><v-icon :color="item.cumple?'success':'error'" :icon="item.cumple?'mdi-check-circle':'mdi-close-circle'"/></template></v-list-item></v-list></v-card-text></v-card></v-dialog>
  </AppFrame>
</template>
<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import AppFrame from '@/components/AppFrame.vue';import api from '@/services/api';const records=ref<any[]>([]),machines=ref<any[]>([]),technicians=ref<any[]>([]),loading=ref(false),dialog=ref(false),detail=ref<any>();const filters=reactive({fecha:new Date().toISOString().slice(0,10),maquina:null as string|null,tecnico:null as string|null});const headers=[{title:'Fecha',key:'fecha_hora'},{title:'Máquina',key:'maquina.nombre'},{title:'Técnico',key:'tecnico.nombre'},{title:'Evidencia',key:'evidencia',sortable:false},{title:'Estado',key:'estado'},{title:'',key:'actions',sortable:false}];const dateOnly=(x:string)=>new Date(x).toLocaleDateString(),timeOnly=(x:string)=>new Date(x).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}),initials=(x?:string)=>(x??'?').split(' ').slice(0,2).map(a=>a[0]).join('').toUpperCase();async function load(){loading.value=true;try{records.value=(await api.get('/admin/mantenimientos',{params:filters})).data}finally{loading.value=false}}async function openDetail(id:string){detail.value=(await api.get(`/admin/mantenimientos/${id}`)).data;dialog.value=true}function clearFilters(){filters.fecha='';filters.maquina=null;filters.tecnico=null;load()}onMounted(async()=>{[machines.value,technicians.value]=await Promise.all([api.get('/admin/maquinas').then(r=>r.data),api.get('/admin/tecnicos').then(r=>r.data)]);load()})</script><style scoped>.heading{align-items:center;display:flex;justify-content:space-between}.eyebrow{color:#1976d2;font-size:.75rem;font-weight:800;letter-spacing:.14em}.filter-card,.panel{border:1px solid #e5e7eb;box-shadow:0 10px 26px rgba(15,23,42,.04)!important}.empty-evidence{align-items:center;color:#64748b;display:flex;flex-direction:column;gap:10px;height:330px;justify-content:center}.audio{width:100%}@media(max-width:600px){.heading{align-items:flex-start;flex-direction:column}}</style>
